// The files of the erased clients (email attachments), 100 per request.
const row = $input.first().json;
const paths = ((row.result && row.result.storage_paths) || []).filter((p) => typeof p === 'string' && p);
const base = String(row.supabase_url || '').replace(/\/$/, '');
if (!paths.length) return [];
if (!/^https:\/\//.test(base)) {
  return [{ json: { skip: true, error: 'platform_settings.supabase_url is not set (see 0046)', count: paths.length } }];
}
const out = [];
for (let i = 0; i < paths.length; i += 100) {
  out.push({ json: { skip: false, url: `${base}/storage/v1/object/email-attachments`, prefixes: paths.slice(i, i + 100) } });
}
return out;

// A file that couldn't be deleted is logged (as *_failed, so the health
// alerts and the Problems page show it). The client's data in the database is
// already gone; the paths are kept so the files can be removed by hand.
const out = [];
$input.all().forEach((it, i) => {
  const req = $('Files To Delete').all()[i]?.json || {};
  const status = Number(it.json.statusCode || 0);
  if (req.skip || !(status >= 200 && status < 300)) {
    out.push({ json: { error: req.error || `Storage answered HTTP ${status || 'no response'}`, count: (req.prefixes || []).length || req.count || 0, paths: req.prefixes || [] } });
  }
});
return out;

